add_action( 'woocommerce_cart_totals_after_order_total', 'perfectpixel_total_savings_row' );
add_action( 'woocommerce_review_order_after_order_total', 'perfectpixel_total_savings_row' );

function perfectpixel_total_savings_row() {
	if ( ! WC()->cart ) {
		return;
	}
	$savings = 0.0;
	foreach ( WC()->cart->get_cart() as $item ) {
		$product = $item['data'];
		if ( ! $product || ! $product->is_on_sale() ) {
			continue;
		}
		$regular = (float) wc_get_price_to_display( $product, array( 'price' => $product->get_regular_price() ) );
		$active  = (float) wc_get_price_to_display( $product );
		if ( $regular > $active ) {
			$savings += ( $regular - $active ) * $item['quantity'];
		}
	}
	$savings += (float) WC()->cart->get_discount_total();
	if ( WC()->cart->display_prices_including_tax() ) {
		$savings += (float) WC()->cart->get_discount_tax();
	}
	if ( $savings <= 0 ) {
		return;
	}
	printf(
		'<tr class="perfectpixel-total-savings"><th>%1$s</th><td data-title="%1$s"><strong>%2$s</strong></td></tr>',
		esc_html( '{{savings_label}}' ),
		wp_kses_post( wc_price( $savings ) )
	);
}
